"""Build an offline research report and searchable title catalogue."""
from pathlib import Path
import html
import json

P=Path(__file__).resolve().parent
read=lambda name: json.loads((P/name).read_text(encoding='utf-8'))
ed=read('editorial.json'); rows=read('classified.json'); stats=read('analysis.json'); manifest=read('manifest.json')
by_id={r['id']:r for r in rows}
e=html.escape
def video(vid):
 r=by_id[vid]
 return f'<a href="{e(r["url"])}" target="_blank" rel="noopener noreferrer">{e(r["title"])}</a> <small>{e(r["channel"])}</small>'
def local(path):
 return f'<a href="../../../../{e(path)}">{e(path)}</a>'

modes=''.join(f'<article class="mode"><p class="eyebrow">{e(x["name"])}</p><h3>{e(x["question"])}</h3><p>{e(x["ada"])}</p><div class="examples"><strong>Title examples, not video reviews</strong><ul>'+''.join(f'<li>{video(v)}</li>' for v in x['example_ids'])+'</ul></div></article>' for x in ed['modes'])
def bars(values):
 return ''.join(f'<div class="barrow"><span>{e(k)}</span><span class="track"><span style="width:{v/10:.1f}%"></span></span><b>{v}</b></div>' for k,v in values.items())
channel_table=''.join(f'<tr><td>{e(k)}</td><td>{v}</td></tr>' for k,v in stats['channel_counts'].items())
artifacts=''.join(f'<article class="candidate" id="artifact-{e(x["id"])}"><div><p class="eyebrow">{i:02d} / {e(x["learn"])}</p><h3>{e(x["title"])}</h3><p class="question">{e(x["question"])}</p></div><div class="outcomes"><p><strong>Precision</strong> {e(x["precision"])}</p><p><strong>Other outcome</strong> {e(x["failure"])}</p></div><p class="scope">{e(x["scope"])}</p></article>' for i,x in enumerate(ed['artifacts'],1))
audit=''.join(f'<article><h3>{e(x["name"])}</h3><p>{e(x["finding"])}</p><ul>'+''.join(f'<li>{local(path)}</li>' for path in x['paths'])+'</ul></article>' for x in ed['source_findings'])
references=''.join(f'<li><a href="{e(x["url"])}">{e(x["label"])}</a></li>' for x in ed['references'])
payload=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')
topics=''.join(f'<option>{e(k)}</option>' for k in stats['topic_cue_counts'])
hooks=''.join(f'<option>{e(k)}</option>' for k in stats['hook_cue_counts'])
channels=''.join(f'<option>{e(k)}</option>' for k in stats['channel_counts'])

page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(ed['title'])} · Endless Museum</title><style>
:root{{--ink:#252824;--muted:#697068;--paper:#eeeae2;--white:#fcfbf8;--line:#d4d1c8;--accent:#8d3f2b;--green:#345e51}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--paper);color:var(--ink);font:18px/1.5 Georgia,serif}}a{{color:var(--accent);text-underline-offset:3px}}nav{{padding:18px 4vw;display:flex;flex-wrap:wrap;gap:20px;border-bottom:1px solid var(--line);font:13px/1.5 system-ui}}main{{max-width:1200px;margin:auto;padding:40px 28px}}h1{{font-size:clamp(42px,7vw,84px);max-width:950px;line-height:1.02;letter-spacing:-.04em;margin:20px 0 24px}}h2{{font-size:32px;line-height:1.18;margin:15px 0 24px}}h3{{font-size:23px;line-height:1.2;margin:8px 0 15px}}p{{margin:0 0 17px}}.eyebrow{{font:12px/1.5 system-ui;text-transform:uppercase;letter-spacing:.09em;color:var(--muted)}}.lead{{font-size:25px;max-width:850px}}.note{{font:14px/1.6 system-ui;color:var(--muted);max-width:880px}}.facts{{display:flex;gap:12px;margin:28px 0;flex-wrap:wrap}}.fact{{background:var(--white);padding:20px 25px;border:1px solid var(--line);flex:1;min-width:160px;font:13px system-ui}}.fact strong{{display:block;font:44px Georgia;margin-bottom:6px}}.reading{{max-width:840px;margin:48px auto}}.reading li{{margin-bottom:12px}}.modes{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}.mode{{background:var(--white);border:1px solid var(--line);padding:25px}}.examples{{border-top:1px solid var(--line);padding-top:15px;font:13px/1.5 system-ui}}.examples li{{margin:10px 0}}small{{display:block;color:var(--muted);font:11px/1.5 system-ui}}section{{margin:52px 0;scroll-margin-top:20px}}.bars{{font:13px system-ui;background:var(--white);padding:22px;border:1px solid var(--line)}}.barrow{{display:grid;grid-template-columns:230px 1fr 40px;gap:14px;align-items:center;margin:15px 0}}.track{{height:9px;background:#eeece5}}.track span{{display:block;height:100%;background:var(--green)}}.barrow b{{text-align:right}}details{{margin:22px 0;padding:18px;background:var(--white);border:1px solid var(--line)}}summary{{font:15px system-ui;cursor:pointer}}table{{border-collapse:collapse;width:100%;font:14px/1.5 system-ui;margin-top:20px}}th,td{{padding:12px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}}.candidate{{background:var(--white);border:1px solid var(--line);margin:16px 0;padding:25px;display:grid;grid-template-columns:1fr 1fr;gap:10px 36px}}.candidate .question{{font-style:italic;font-size:20px}}.outcomes{{font-size:17px}}.outcomes strong{{font:12px system-ui;letter-spacing:.04em;text-transform:uppercase;display:block;color:var(--green);margin-bottom:6px}}.scope{{grid-column:1/-1;padding-top:12px;border-top:1px solid var(--line);font:13px/1.6 system-ui;color:var(--muted);margin:0}}.audit li{{font:12px/1.5 system-ui;overflow-wrap:anywhere}}.audit article{{padding:10px 0 20px;border-bottom:1px solid var(--line)}}.brief{{border-left:4px solid var(--accent);padding:20px;background:var(--white);font:15px/1.7 system-ui}}.filters{{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px}}input,select,button{{padding:12px;font:14px system-ui;border:1px solid var(--line);border-radius:3px;background:var(--white);color:var(--ink)}}input{{grid-column:1/-1}}button{{cursor:pointer}}.paging{{display:flex;gap:18px;align-items:center;justify-content:space-between;font:13px system-ui;margin:18px 0}}#catalogue td:first-child{{width:49%}}.tag{{display:inline-block;padding:3px 6px;margin:2px;background:#e6eae4;border-radius:3px;font-size:11px}}footer{{padding:30px 4vw;border-top:1px solid var(--line);font:13px system-ui}}@media(max-width:740px){{.modes,.candidate{{grid-template-columns:1fr}}main{{padding:25px 16px}}.filters{{grid-template-columns:1fr}}.barrow{{grid-template-columns:150px 1fr 32px;font-size:11px}}.outcomes{{margin-top:8px}}}}@media print{{nav,#browse,button{{display:none}}body{{background:white;font-size:11pt}}main{{padding:0}}h1{{font-size:38pt}}.candidate,.mode{{break-inside:avoid}}.facts strong{{font-size:24pt}}a{{color:inherit}}}}
</style></head><body><nav><strong>ENDLESS MUSEUM / PHYSICS RESEARCH</strong><a href="#questions">Watching questions</a><a href="#ada">20 apparatus</a><a href="#existing">Existing code</a><a href="#browse">1,000 titles</a><a href="REPORT.md">Full report</a><a href="classified.csv">CSV</a></nav><main>
<p class="eyebrow">7 October 2026 / public title study + design interpretation</p><h1>{e(ed['title'])}</h1><p class="lead">{e(ed['finding'])}</p><p>{e(ed['revision'])}</p>
<div class="facts"><div class="fact"><strong>1,000</strong>unique Shorts title records</div><div class="fact"><strong>17</strong>public channel lists represented</div><div class="fact"><strong>8</strong>editorial families of questions</div><div class="fact"><strong>20</strong>proposed Ada encounters</div></div>
<p class="note">{e(ed['method'])}</p><p class="note">{e(ed['limits'])}</p>
<section id="questions"><p class="eyebrow">Interpretation illustrated by actual titles</p><h2>The body carries a question</h2><div class="modes">{modes}</div></section>
<article class="reading"><h2>From a watched clip to a room you can change</h2><p>A title can promise an answer. In the museum, the arrangement must make that promise visible: the cup, the gap, the hinge, the approaching body. The visitor supplies the next action. A clean catch is a complete event; a miss offers information for the next attempt.</p><ol>{''.join('<li>'+e(x)+'</li>' for x in ed['rhythm'])}</ol><p>My design hypothesis is that a readable uncertainty is more useful here than continuous spectacle. If nothing can be predicted, the outcome loses its relation to the player's decision. If nothing can vary, the apparatus becomes a demonstration to watch once.</p><p>Garry's Mod's official description places tool use and player-made contraptions at its centre. <a href="https://gmod.facepunch.com/">That is a useful precedent</a>. Ada can provide small initial tasks inside such freedom, then let the same pieces be used otherwise. The <a href="https://store.steampowered.com/app/1403040/Physics_Sandbox_VR/">Physics Sandbox VR developer description</a> likewise lists domino arrangements, linked bodies and thrusters; this is a genre precedent, not a review of how well that game works.</p><p class="brief">{e(ed['compact_brief'])}</p></article>
<section id="counts"><p class="eyebrow">Reproducible first-pass index</p><h2>What the titles actually name</h2><p class="note">Each bar is out of 1,000. A title may match several categories. These are transparent keyword rules, not a completed visual coding of the videos. {stats['no_topic_cue']} titles have no match under these topic rules; {stats['no_hook_cue']} have no match under the hook rules. A non-match does not mean that the video lacks a topic or a hook.</p><div class="bars">{bars(stats['topic_cue_counts'])}</div><details><summary>Hook cues, channel coverage and sampling limitations</summary><div class="bars">{bars(stats['hook_cue_counts'])}</div><table><thead><tr><th>Channel</th><th>Selected titles</th></tr></thead><tbody>{channel_table}</tbody></table><p class="note">The four VR/sandbox channel lists contribute 52 titles. Most of this sample comes from real-world demonstrations, mechanisms and physical challenges. The two Action Lab channels share a creator. Channel selection and English wording bias the sample. The exact failed handles and missing Shorts tabs remain in the manifest. No ranking of creators or claims about retention are inferred.</p><p><a href="manifest.json">Collection manifest</a> · <a href="analysis.json">Counts and matching rules</a> · <a href="sample.csv">Raw selected titles</a></p></details></section>
<section id="ada"><p class="eyebrow">Proposals based on your examples / no museum changes</p><h2>Twenty questions to put in the museum</h2><p>{e(ed['curriculum'])}</p>{artifacts}</section>
<section class="audit" id="existing"><p class="eyebrow">Source inspection / no new Godot run</p><h2>What the project already gives us</h2>{audit}<p class="note">Godot documents that a hinge motor is disabled by default and must be enabled to turn the joint. <a href="https://docs.godotengine.org/en/stable/classes/class_hingejoint3d.html">HingeJoint3D reference</a>. The flags above are research findings, not repaired or runtime-verified claims.</p></section>
<article class="reading"><h2>The first five builds</h2><ol>{''.join('<li>'+e(x)+'</li>' for x in ed['priorities'])}</ol><p>Keep two-sphere flight as the continuing ability route. Use these small apparatus to make the forces legible around it. The robot dog and robot-arm duet need more implementation and can follow after the basic contacts and constraints are trustworthy.</p><p>For teaching, the success criterion is stronger than a funny ending: the student can name the relation, change a relevant parameter, predict a difference and reconstruct the minimal working mechanism. Reflection can stay with the competing intentions and the aftermath.</p><h3>Primary references</h3><ul>{references}</ul><p><a href="editorial.json">Editable interpretations and apparatus plan</a> · <a href="../2026-10-07-forces-experiments-and-escape/index.html">Earlier fourteen-scene proposal</a></p></article>
<section id="browse"><p class="eyebrow">Audit the sample yourself</p><h2>Search all 1,000 title records</h2><p class="note">Filters use title cues only. Open the source video to inspect the actual reveal. No video playback is embedded or autoplayed here.</p><div class="filters"><input id="search" aria-label="Search titles" placeholder="Search: ball, hinge, robot, fit, domino…"><select id="channel" aria-label="Channel"><option value="">All channels</option>{channels}</select><select id="topic" aria-label="Topic cue"><option value="">All topic cues</option>{topics}<option value="__unresolved">No topic-rule match</option></select><select id="hook" aria-label="Hook cue"><option value="">All hook cues</option>{hooks}</select></div><div class="paging"><button id="prev">Previous</button><span id="status" aria-live="polite"></span><button id="next">Next</button></div><table id="catalogue"><thead><tr><th>Title / source</th><th>Topic cues</th><th>Hook cues</th></tr></thead><tbody id="records"></tbody></table><noscript><p>Use <a href="classified.csv">the CSV catalogue</a> when JavaScript is unavailable.</p></noscript></section></main><footer>Research and proposals only. Museum runtime, canonical order, tutorial.md and final.md remain unchanged. Raw metadata and rebuild scripts are kept alongside this report.</footer><script id="data" type="application/json">{payload}</script>
<script>
const rows=JSON.parse(document.getElementById('data').textContent);let page=0;const size=40;
const fields=['search','channel','topic','hook'].map(id=>document.getElementById(id));
function tags(td,values){{if(!values.length){{td.textContent='No rule match';return;}}for(const value of values){{const tag=document.createElement('span');tag.className='tag';tag.textContent=value;td.append(tag);}}}}
function render(){{const [q,c,t,h]=fields.map(x=>x.value);const selected=rows.filter(r=>(!q||(r.title+' '+r.channel).toLowerCase().includes(q.toLowerCase()))&&(!c||r.channel===c)&&(!t||(t==='__unresolved'?!r.topic_cues.length:r.topic_cues.includes(t)))&&(!h||r.hook_cues.includes(h)));const max=Math.max(0,Math.ceil(selected.length/size)-1);page=Math.min(page,max);const body=document.getElementById('records');body.replaceChildren();for(const r of selected.slice(page*size,(page+1)*size)){{const tr=document.createElement('tr');const title=document.createElement('td');const link=document.createElement('a');link.href=r.url;link.textContent=r.title;link.target='_blank';link.rel='noopener noreferrer';title.append(link);const sub=document.createElement('small');sub.textContent=r.channel+' / list position '+r.list_position;title.append(sub);const topic=document.createElement('td');tags(topic,r.topic_cues);const hook=document.createElement('td');tags(hook,r.hook_cues);tr.append(title,topic,hook);body.append(tr);}}document.getElementById('status').textContent=selected.length+' records · page '+(page+1)+' of '+(max+1);document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=page>=max;}}
for(const f of fields)f.addEventListener('input',()=>{{page=0;render();}});document.getElementById('prev').onclick=()=>{{page--;render();}};document.getElementById('next').onclick=()=>{{page++;render();}};render();
</script></body></html>'''
(P/'index.html').write_text(page,encoding='utf-8')

md=[f'# {ed["title"]}',ed['finding'],ed['revision'],'## Sample and limits',ed['method'],ed['limits'],'## Eight physical questions']
for mode in ed['modes']:
 md.extend([f'### {mode["name"]}: {mode["question"]}',mode['ada']])
 for vid in mode['example_ids']:
  r=by_id[vid];md.append(f'- [{r["title"]}]({r["url"]}) — {r["channel"]}')
md.extend(['## A working rhythm','\n'.join(f'{i}. {x}' for i,x in enumerate(ed['rhythm'],1)),ed['compact_brief'],'## Twenty candidate encounters',ed['curriculum']])
for i,x in enumerate(ed['artifacts'],1):
 md.extend([f'### {i}. {x["title"]}',f'**Question:** {x["question"]}',f'**Learn:** {x["learn"]}',f'**Precision:** {x["precision"]}',f'**Other outcome:** {x["failure"]}',f'**Scope:** {x["scope"]}'])
md.extend(['## Source findings — not runtime verification'])
for x in ed['source_findings']:
 md.extend([f'### {x["name"]}',x['finding'],'\n'.join(f'- [{p}](../../../../{p})' for p in x['paths'])])
md.extend(['## First builds','\n'.join(f'{i}. {x}' for i,x in enumerate(ed['priorities'],1)),'## Topic-cue counts',stats['method'],'\n'.join(f'- {k}: {v}' for k,v in stats['topic_cue_counts'].items()),f'No topic-rule match: {stats["no_topic_cue"]}. No hook-rule match: {stats["no_hook_cue"]}.','## Files','- [Searchable report](index.html)\n- [Raw selected titles](sample.csv)\n- [Classified titles](classified.csv)\n- [Collection manifest](manifest.json)\n- [Counts and lexical rules](analysis.json)\n- [Editable design interpretation](editorial.json)','## References','\n'.join(f'- [{x["label"]}]({x["url"]})' for x in ed['references'])])
(P/'REPORT.md').write_text('\n\n'.join(md)+'\n',encoding='utf-8')
print(f'Built searchable report: {len(rows)} titles, {len(ed["modes"])} question families, {len(ed["artifacts"])} candidates.')
